// Generates build/index.js and build/index.d.ts which re-export every
// protobuf-es module generated by buf, so consumers can keep importing the
// package root: import * as Proto from "docframe-types".
import { readdirSync, statSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { join, relative, resolve, sep } from "node:path";

const root = process.argv[2] ?? "build";

function collect(dir) {
  const result = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      result.push(...collect(full));
    } else if (entry.endsWith("_pb.js")) {
      result.push("./" + relative(root, full).split(sep).join("/"));
    }
  }
  return result.sort();
}

const modules = collect(root);

// Every generated module must export distinct names, otherwise index.js would
// silently keep the last one while index.d.ts becomes ambiguous.
const require = createRequire(import.meta.url);
const seen = new Map();
for (const m of modules) {
  for (const name of Object.keys(require(resolve(root, m)))) {
    if (seen.has(name)) {
      console.error(`duplicate export "${name}" in ${seen.get(name)} and ${m}`);
      process.exit(1);
    }
    seen.set(name, m);
  }
}
const js =
  "// Generated by tools/ts-index/gen-index.mjs. DO NOT EDIT.\n\"use strict\";\n" +
  "Object.defineProperty(exports, \"__esModule\", { value: true });\n" +
  modules.map((m) => `Object.assign(exports, require("${m}"));`).join("\n") +
  "\n";
const dts =
  "// Generated by tools/ts-index/gen-index.mjs. DO NOT EDIT.\n" +
  modules.map((m) => `export * from "${m}";`).join("\n") +
  "\n";

writeFileSync(join(root, "index.js"), js);
writeFileSync(join(root, "index.d.ts"), dts);
console.log(`index: ${modules.length} modules`);
